'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro = n => new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format((n||0)/100);
const day = value => value ? new Date(value+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'}) : 'Première visite';
const today = () => { const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const initials = p => ((p.first_name?.[0]||'')+(p.last_name?.[0]||'')).toUpperCase();
const name = p => esc((p.first_name||'')+' '+(p.last_name||''));
const paths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',patients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',receipt:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 7h6 M9 11h6 M9 15h3',chart:'M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',chevron:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',file:'M14 2H5v20h14V7z M14 2v6h5 M8 13h8 M8 17h6',edit:'m16 3 5 5-12 12-5 1 1-5z M14 5l5 5',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',link:'m9 15 6-6 M7 14l-2 2a4 4 0 0 0 6 6l4-4 M17 10l2-2a4 4 0 0 0-6-6L9 6',alert:'m12 3 10 18H2z M12 9v4 M12 17h.01',mail:'M3 5h18v14H3z m0 0 9 7 9-7',folder:'M3 6h6l2 3h10v11H3z',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10',lock:'M5 11h14v10H5z M8 11V7a4 4 0 1 1 8 0v4',back:'M19 12H5 m6-6-6 6 6 6',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7'};
const icon = id => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.file}"/></svg>`;
const btn = (label, action, attrs='', cls='') => `<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const input = (label, key, value='', type='text', attrs='') => `<label class="field">${esc(label)}<input class="input" type="${type}" name="${esc(key)}" value="${esc(value)}" ${attrs}></label>`;
const area = (label,key,value='',attrs='') => `<label class="field">${esc(label)}<textarea name="${esc(key)}" rows="4" ${attrs}>${esc(value)}</textarea></label>`;
const empty = (title,desc,action='') => `<div class="empty">${icon('folder')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;
const statusBadge = inv => inv.kind==='credit'?'<span class="badge subtle">Avoir</span>':inv.status==='draft'?'<span class="badge warm">Brouillon</span>':inv.status==='replaced'?`<span class="badge subtle">${inv.legacy?'Annulée':'Remplacée'}</span>`:inv.paid_cents>=inv.total_cents?'<span class="badge">Réglée</span>':'<span class="badge warm">À régler</span>';
let state={route:'home',patient:null,consult:null,tab:'consultation',settings:null,dashboard:null,patients:[],invoices:[],demo:false};
let dirtyP={},dirtyC={},saveTimer=null,saveChain=Promise.resolve(),saving=false,saveError=false,toastTimer=null,searchSerial=0;
let invoiceEdit=null,settingsEdit=null,includeArchived=false;
try { if(localStorage.getItem('cabinet-theme')==='dark')document.body.classList.add('dark'); } catch(_){}

async function api(path,body){
  const res=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Cabinet-Token':$('meta[name="cabinet-token"]').content},body:body===undefined?undefined:JSON.stringify(body)});
  const data=await res.json();if(!res.ok){const error=new Error(data.error||'Une erreur est survenue.');error.status=res.status;throw error;}return data;
}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6500);}
function errorBox(error){const target=$('#modal[open] #modal-error');if(target){target.textContent=error.message;target.hidden=false;}else toast(error.message);}
function updateSave(label){const target=$('#save-state');if(target){target.classList.toggle('error',saveError);target.innerHTML=icon(saveError?'alert':saving?'clock':'check')+`<span>${esc(label|| (saveError?'Non enregistré':saving?'Enregistrement…':'Enregistré sur cet ordinateur'))}</span>`+(saveError?btn('Réessayer','retry-save','','tiny'):'');}}
function schedule(){saveError=false;updateSave('Modifications en cours…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>flush().catch(e=>toast(e.message)),650);}
function flush(){
  clearTimeout(saveTimer);
  const operation=async()=>{
    if(!state.patient)return;
    saving=true;updateSave();
    try{
      while(Object.keys(dirtyP).length||Object.keys(dirtyC).length){
        if(Object.keys(dirtyP).length){
          const changes={...dirtyP},p=state.patient;dirtyP={};
          try{const saved=await api('/patients/'+p.id,{...changes,version:p.version});p.version=saved.version;p.updated_at=saved.updated_at;}
          catch(e){dirtyP={...changes,...dirtyP};throw e;}
        }
        if(Object.keys(dirtyC).length){
          const changes=structuredClone(dirtyC),co=state.consult;dirtyC={};
          try{const saved=await api('/consultations/'+co.id,{...changes,version:co.version});co.version=saved.version;co.updated_at=saved.updated_at;const old=state.patient.consultations.find(c=>c.id===co.id);if(old)Object.assign(old,co);}
          catch(e){dirtyC={...changes,...dirtyC};throw e;}
        }
      }
      saveError=false;
    }catch(e){saveError=true;throw e;}finally{saving=false;updateSave();}
  };
  saveChain=saveChain.then(operation,operation);return saveChain;
}
window.addEventListener('beforeunload',e=>{if(saving||Object.keys(dirtyP).length||Object.keys(dirtyC).length){e.preventDefault();e.returnValue='';}});

function shell(content){
  const navs=[['home','home','Vue d’ensemble'],['patients','patients','Patients'],['accounting','receipt','Facturation'],['statistics','chart','Statistiques'],['orphans','patients','À rattacher'],['settings','settings','Paramètres']];
  const profile=state.settings?.practice.name||'Votre cabinet';
  $('#app').innerHTML=`${state.demo?'<div class="demo-banner">DÉMONSTRATION · Données fictives · Base séparée de votre cabinet</div>':''}<div class="layout"><aside class="sidebar"><div class="brand"><img src="/icon.svg" alt=""><div>Mon Cabinet<span>d’Ostéo</span></div></div><nav class="nav-list" aria-label="Navigation principale">${navs.map(([id,ic,label])=>`${id==='settings'?'<div class="nav-divider"></div>':''}<button type="button" class="nav-btn ${state.route===id||(id==='patients'&&state.route==='patient')?'active':''}" data-nav="${id}" aria-label="${label}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-footer"><span class="local-dot"></span>Votre espace local<br><span class="small">Version ${esc(state.version)}</span></div></aside><div class="main-shell"><header class="topbar"><div class="topbar-label">${state.route==='patient'?'Patients / Dossier de consultation':'Un espace pour votre pratique, au quotidien'}</div><div class="profile"><span class="profile-text">${esc(profile)}</span><div class="avatar">${esc(profile.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase())}</div></div></header><main class="content" id="main">${content}</main></div></div>`;
}

async function navigate(route){
  await flush();state.route=route;state.patient=null;state.consult=null;dirtyP={};dirtyC={};
  if(route==='home'||route==='statistics')state.dashboard=await api('/dashboard');
  if(route==='patients')state.patients=await api('/patients'+(includeArchived?'?archived=1':''));
  if(route==='accounting'){[state.invoices,state.mclAccounting]=await Promise.all([api('/invoices'),api('/migration/accounting')]);}
  if(route==='orphans')state.orphans=await api('/migration/orphans');
  if(route==='settings')settingsEdit=structuredClone(state.settings);
  history.replaceState(null,'','#'+route);render();window.scrollTo(0,0);
}
function render(){if(state.route==='home')renderHome();if(state.route==='patients')renderPatients();if(state.route==='patient')renderPatient();if(state.route==='accounting')renderAccounting();if(state.route==='statistics')renderStatistics();if(state.route==='settings')renderSettings();if(state.route==='orphans')renderOrphans();}

function recentRows(rows){return rows.length?rows.map(r=>`<div class="list-row"><div class="avatar">${initials(r)}</div><div class="grow"><button class="link" data-patient="${r.patient_id}" data-consult="${r.id}">${name(r)}</button><div class="small muted truncate">${esc(r.motif||'Consultation à compléter')}</div></div><div class="small muted">${day(r.date)}</div></div>`).join(''):empty('Une journée à construire','Créez une fiche patient, puis ouvrez sa première consultation.');}
function renderHome(){
  const d=state.dashboard;
  shell(`<div class="page-head"><div><div class="eyebrow">${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><h1 style="margin-top:8px">Bienvenue au cabinet</h1><p>Retrouvez vos patients et reprenez le fil de vos consultations.</p></div>${btn(icon('plus')+'Nouveau patient','new-patient','','primary')}</div><div class="metrics"><div class="metric"><span>Consultations aujourd’hui</span><div class="value">${d.totals.today}</div><span>Votre activité du jour</span></div><div class="metric"><span>Patients</span><div class="value">${d.totals.patients}</div><span>Dossiers du cabinet</span></div><div class="metric emphasis"><span>À facturer</span><div class="value">${d.pending.length}</div><span>Séances facturables</span></div><div class="metric"><span>Recettes enregistrées</span><div class="value">${euro(d.totals.receipts_cents)}</div><span>Depuis l’ouverture du cabinet local</span></div></div><div class="home-grid"><section class="card"><div class="card-head"><h2>Dernières consultations</h2>${btn('Tous les patients','nav-patients','','quiet tiny')}</div>${recentRows(d.recent)}</section><div class="stack"><section class="card"><div class="card-head"><h2>À terminer</h2><span class="badge warm">${d.pending.length}</span></div>${d.pending.length?d.pending.slice(0,6).map(r=>`<div class="list-row"><div class="grow"><button class="link" data-patient="${r.patient_id}" data-consult="${r.id}">${name(r)}</button><div class="small muted">Séance du ${day(r.date)}</div></div>${icon('arrow')}</div>`).join(''):empty('Tout est à jour','Aucune consultation en attente de facturation.')}</section><section class="card card-pad"><div class="eyebrow">Votre prochain geste</div><h2 style="margin:10px 0">Ouvrir une fiche</h2><p class="muted small" style="margin-bottom:16px">Un nom, un prénom ou un téléphone suffit pour retrouver un patient.</p>${btn(icon('search')+'Rechercher un patient','nav-patients')}</section>${!state.settings.practice.siret?`<section class="card card-pad"><h3>Préparer vos factures</h3><p class="muted small" style="margin:8px 0 14px">Renseignez les coordonnées et identifiants professionnels du cabinet.</p>${btn('Configurer mon cabinet','nav-settings','','tiny')}</section>`:''}</div></div>`);
}
function patientsTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Patient</th><th>Contact</th><th>Dernière consultation</th><th>Séances</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="row"><div class="avatar">${initials(p)}</div><div><button class="link" data-patient="${p.id}">${name(p)}</button>${p.archived?'<span class="badge subtle">Archivée</span>':''}<div class="small muted">${p.birth_date?'Né·e le '+day(p.birth_date):'Date de naissance non renseignée'}</div></div></div></td><td><div>${esc(p.phone||'—')}</div><div class="small muted">${esc(p.email)}</div></td><td>${day(p.last_visit)}</td><td>${p.visits}</td><td>${btn(icon('arrow'),'open-patient',`data-id="${p.id}" aria-label="Ouvrir ${name(p)}"`,'quiet tiny')}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucun patient trouvé','Créez une fiche ou essayez une autre recherche.');}
function renderPatients(){shell(`<div class="page-head"><div><div class="eyebrow">Votre patientèle</div><h1 style="margin-top:8px">Les patients</h1><p>Les informations utiles, à portée de main.</p></div>${btn(icon('plus')+'Nouveau patient','new-patient','','primary')}</div><div class="toolbar"><div class="search">${icon('search')}<input class="input" id="patient-search" placeholder="Rechercher un nom, un téléphone, une ville…" aria-label="Rechercher un patient" autocomplete="off"></div><span class="badge subtle" id="patient-count">${state.patients.length>=500?'500 premiers résultats — affinez la recherche':state.patients.length+' dossiers'}</span><label class="check small"><input type="checkbox" id="include-archived" ${includeArchived?'checked':''}>Inclure les fiches archivées</label></div><section class="card" id="patient-results">${patientsTable(state.patients)}</section>`);}

async function openPatient(id,consultId){
  await flush();state.patient=await api('/patients/'+id);state.route='patient';state.tab='consultation';state.consult=state.patient.consultations.find(c=>c.id===consultId)||state.patient.consultations[0]||null;dirtyP={};dirtyC={};saveError=false;history.replaceState(null,'','#patient/'+id);renderPatient();window.scrollTo(0,0);
}
function informationPanel(){const p=state.patient;return `<details class="card info-panel" open><summary><span>01 · Informations du patient</span><span class="row small muted">Identité & repères ${icon('chevron')}</span></summary><div class="info-body"><div><div class="identity-details">${[['Téléphone',p.phone||'Non renseigné'],['Email',p.email||'Non renseigné'],['Adresse',[p.address,p.postal,p.city].filter(Boolean).join(' · ')||'Non renseignée'],['Naissance',p.birth_date?day(p.birth_date):'Non renseignée'],['Profession / scolarité',p.occupation||'Non renseignée'],['Activités',p.activities||'Non renseignées']].map(([a,b])=>`<div><small>${esc(a)}</small>${esc(b)}</div>`).join('')}</div>${btn(icon('edit')+'Modifier les informations','edit-patient','','quiet tiny')}<label class="field" style="margin-top:14px">Notes importantes à relire<textarea rows="2" data-p="important_notes" placeholder="Préférences, précautions, sujets à aborder…">${esc(p.important_notes)}</textarea></label></div><div class="patient-note"><label class="field">Notes / antécédents<textarea rows="7" data-p="shared_notes" placeholder="Le contexte du patient, conservé d’une séance à l’autre…">${esc(p.shared_notes)}</textarea></label><div class="note-hint" style="margin-top:8px">${icon('link')}Même contenu que dans la consultation</div></div></div></details>`;}
function renderPatient(){const p=state.patient;shell(`<div class="page-head"><div class="patient-name"><div class="avatar">${initials(p)}</div><div><div class="eyebrow">Dossier patient</div><h1 style="margin-top:5px">${name(p)}</h1><p class="small">${p.consultations.length} consultation${p.consultations.length>1?'s':''} · ${p.birth_date?age(p.birth_date)+' ans':'Âge non renseigné'}</p></div></div><div class="row"><div class="save-indicator" id="save-state"></div>${btn(icon('plus')+'Nouvelle consultation','new-consult','','primary')}</div></div>${informationPanel()}<nav class="tabs" aria-label="Rubriques du dossier">${[['consultation','Consultation'],['history','Historique'],['documents','Documents'],['invoices','Factures']].map(([id,label])=>`<button type="button" class="tab ${state.tab===id?'active':''}" data-tab="${id}">${label}${id==='documents'?' · '+p.attachments.length:id==='invoices'?' · '+p.invoices.length:''}</button>`).join('')}</nav><div id="patient-tab">${patientTab()}</div>`);updateSave();}
function age(birth){const t=new Date(),b=new Date(birth+'T12:00:00');return t.getFullYear()-b.getFullYear()-(t.getMonth()<b.getMonth()||(t.getMonth()===b.getMonth()&&t.getDate()<b.getDate())?1:0);}
function activeInvoice(){return state.patient.invoices.find(i=>i.consultation_id===state.consult?.id&&['draft','issued'].includes(i.status)&&i.kind==='invoice');}
function patientTab(){
  const p=state.patient,co=state.consult;
  if(state.tab==='documents')return `<section class="card"><div class="card-head"><h2>Documents du patient</h2>${btn(icon('plus')+'Ajouter un fichier','upload')}</div><input id="attachment-input" type="file" hidden accept=".pdf,.png,.jpg,.jpeg,.txt,.docx,.xlsx,.mp3,.m4a">${p.attachments.length?p.attachments.map(a=>`<div class="list-row">${icon('file')}<div class="grow"><a href="/api/attachments/${a.id}" download>${esc(a.name)}</a><div class="small muted">${Math.round(a.size/1024)} Ko · ${esc(a.created_at.slice(0,10))}</div></div></div>`).join(''):empty('Les documents de ce patient','Ajoutez une image, un PDF ou un document reçu. Maximum 10 Mo par fichier.')}</section>`;
  if(state.tab==='invoices')return `<section class="card"><div class="card-head"><h2>Factures & avoirs</h2><span class="muted small">Liés au dossier</span></div>${invoiceTable(p.invoices)}</section>`;
  if(state.tab==='history')return `<section class="card card-pad"><h2 style="margin-bottom:24px">Le fil des consultations</h2>${p.consultations.length?p.consultations.map(c=>`<article class="history-item"><div class="row spread"><span class="small muted">${day(c.date)}</span>${btn('Ouvrir','select-consult',`data-id="${c.id}"`,'tiny')}</div><h3>${esc(c.motif||'Consultation sans motif')}</h3><p>${esc(c.anamnesis||'Aucune anamnèse renseignée.')}</p>${c.followup?`<div class="inline-note">Prochain rendez-vous : ${esc(c.followup)}</div>`:''}<span class="badge subtle">${c.billable?'Facturable':'Non facturée'}</span></article>`).join(''):empty('Pas encore de consultation','La première séance apparaîtra ici.')}</section>`;
  if(!co)return `<section class="card">${empty('Une première consultation','Ouvrez la séance pour saisir le motif, l’anamnèse et les notes.',btn(icon('plus')+'Commencer la consultation','new-consult','','primary'))}</section>`;
  const invoice=activeInvoice();
  return `<div class="consult-grid"><section class="card"><div class="card-head"><div><div class="eyebrow">${esc(state.settings.templates.find(t=>t.id===co.template_id)?.name||'Consultation')}</div><h2 style="margin-top:5px">Séance du ${day(co.date)}</h2></div><span class="badge subtle">${co.date===today()?'Aujourd’hui':'Séance enregistrée'}</span></div><div class="card-pad consult-form"><label class="field">Motif de consultation<textarea data-c="motif" rows="2" placeholder="Pourquoi le patient consulte-t-il aujourd’hui ?">${esc(co.motif)}</textarea></label><label class="field">Anamnèse<textarea data-c="anamnesis" rows="8" placeholder="Contexte, évolution, symptômes, éléments rapportés…">${esc(co.anamnesis)}</textarea></label><label class="field">Notes / antécédents<span class="note-hint">${icon('link')}Partagé avec le premier volet du dossier patient</span><textarea data-p="shared_notes" rows="5" placeholder="Antécédents et notes durables du patient…">${esc(p.shared_notes)}</textarea></label>${co.fields.filter(f=>!['motif','anamnesis'].includes(f.key)).map(f=>customField(f,co.custom[f.key])).join('')}<details><summary class="muted small" style="cursor:pointer;margin-top:12px">Pour le prochain rendez-vous</summary><textarea data-c="followup" aria-label="Notes pour le prochain rendez-vous" rows="3" style="margin-top:12px" placeholder="Un détail à reprendre lors de la prochaine séance…">${esc(co.followup)}</textarea></details></div></section><aside class="side-stack"><section class="card card-pad"><div class="row spread"><h3>Fin de consultation</h3>${icon('receipt')}</div><div style="margin-top:20px"><label class="switch"><input type="checkbox" data-c="billable" ${co.billable?'checked':''} ${invoice||co.legacy_billed?'disabled title="Une facture existe pour cette séance"':''}>Facturer</label><p class="side-label" id="billing-explanation">${co.billable?'Cette séance entre dans le suivi de facturation.':'Consultation conservée sans facturation.'}</p>${co.legacy_billed?'<div class="inline-note">Déjà facturée dans MonCabinetLibéral. Historique financier conservé pour reprise.</div>':invoice?btn(invoice.status==='draft'?'Reprendre le brouillon':'Voir la facture','view-invoice',`data-id="${invoice.id}"`,'primary'):btn('Préparer la facture '+icon('arrow'),'prepare-invoice',`id="prepare-invoice" ${co.billable?'':'disabled'}`,'primary')}</div><div style="margin-top:12px">${btn(icon('download')+'Compte-rendu PDF','consult-pdf')}</div></section><section class="card card-pad"><div class="row spread"><h3>Antécédents structurés</h3>${btn('+','new-antecedent','aria-label="Ajouter un antécédent"','quiet tiny')}</div>${p.antecedents.length?p.antecedents.map(a=>`<div class="antecedent"><div class="row spread"><span class="small ${a.important?'':'muted'}">${a.important?'● ':''}${esc(a.category)}</span>${btn('×','remove-antecedent',`data-id="${a.id}" aria-label="Retirer ${esc(a.label)}"`,'quiet tiny')}</div><h3>${esc(a.label)}</h3>${a.since?`<span class="small muted">${esc(a.since)}</span>`:''}${a.detail?`<p class="small muted">${esc(a.detail)}</p>`:''}</div>`).join(''):'<p class="muted small" style="margin-top:14px">Aucun antécédent structuré. Les notes libres restent disponibles dans le dossier.</p>'}</section><section class="card card-pad"><h3>Historique de saisie</h3><p class="muted small" style="margin:10px 0">Les modifications du dossier et de la consultation sont conservées.</p>${btn(icon('clock')+'Voir les modifications','audit-consult','','tiny')}</section></aside></div>`;
}
function customField(f,v){if(f.kind==='checkbox')return `<label class="field check"><span>${esc(f.label)}</span><input type="checkbox" data-custom="${f.key}" ${v?'checked':''}></label>`;if(f.kind==='select')return `<label class="field">${esc(f.label)}<select data-custom="${f.key}"><option value="">Non renseigné</option>${(f.options||[]).map(o=>`<option ${v===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;return `<label class="field">${esc(f.label)}${f.kind==='text'?`<input class="input" data-custom="${f.key}" value="${esc(v||'')}">`:`<textarea data-custom="${f.key}" rows="3">${esc(v||'')}</textarea>`}</label>`;}

function invoiceTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Document</th><th>Date</th><th>Destinataire</th><th>État</th><th>Total</th><th></th></tr></thead><tbody>${rows.map(i=>`<tr><td><button class="link" data-action="view-invoice" data-id="${i.id}">${esc(i.number||'Brouillon')}</button></td><td>${esc(i.date.split('-').reverse().join('/'))}</td><td>${name(i.recipient)}</td><td>${statusBadge(i)}${i.legacy?'<span class="badge subtle">MCL</span>':''}${i.discrepancy_cents?'<span class="badge warm">Écart</span>':''}</td><td class="numeric">${euro(i.total_cents)}</td><td>${btn(icon('arrow'),'view-invoice',`data-id="${i.id}" aria-label="Ouvrir le document ${esc(i.number||'brouillon')}"`,'quiet tiny')}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucune facture','Les factures se préparent depuis une consultation avec Facturer activé.');}
function renderAccounting(){const rows=state.invoices;const total=rows.filter(i=>i.status!=='draft').reduce((s,i)=>s+i.total_cents,0);const paid=rows.reduce((s,i)=>s+i.paid_cents,0);shell(`<div class="page-head"><div><div class="eyebrow">Suivi du cabinet</div><h1 style="margin-top:8px">Facturation & règlements</h1><p>Les factures, leurs corrections et les recettes enregistrées dans ce cabinet local.</p></div><a class="btn" href="/api/export/receipts.csv" download>${icon('download')}Exporter les recettes locales</a></div><div class="metrics"><div class="metric"><span>Factures actives</span><div class="value">${rows.filter(i=>i.status==='issued'&&i.kind==='invoice').length}</div></div><div class="metric"><span>Montant net facturé</span><div class="value">${euro(total)}</div><span>Factures et avoirs émis</span></div><div class="metric emphasis"><span>Soldes réglés des factures</span><div class="value">${euro(paid)}</div><span>Soldes MCL + règlements locaux</span></div><div class="metric"><span>Brouillons</span><div class="value">${rows.filter(i=>i.status==='draft').length}</div></div></div>${mclAccountingPanel()}<div class="toolbar"><div class="search">${icon('search')}<input class="input" id="invoice-search" placeholder="Rechercher un numéro ou un destinataire…" aria-label="Rechercher une facture"></div></div>${state.settings.migration?.state==='patients_imported'?'<div class="inline-note" style="margin-bottom:20px">Les anciennes factures et recettes MCL sont conservées dans les données d’import. Elles ne sont pas encore incluses dans ces totaux. Leurs numéros sont réservés.</div>':''}<section class="card" id="invoice-results">${invoiceTable(rows)}</section>`);}
function renderStatistics(){const d=state.dashboard;const chart=(rows,key,format)=>{const max=Math.max(1,...rows.map(r=>r[key]));return rows.length?rows.slice().reverse().map(r=>`<div class="bar-row"><span>${esc(r.month)}</span><div class="bar"><span style="width:${100*r[key]/max}%"></span></div><b>${format(r[key])}</b></div>`).join(''):'<p class="muted" style="padding:24px 0">Les premières consultations feront apparaître votre activité.</p>';};shell(`<div class="page-head"><div><div class="eyebrow">Votre activité</div><h1 style="margin-top:8px">Les repères du cabinet</h1><p>Consultations historiques incluses ; recettes issues uniquement des règlements saisis dans ce cabinet local.</p></div></div><div class="metrics"><div class="metric"><span>Patients</span><div class="value">${d.totals.patients}</div></div><div class="metric"><span>Consultations</span><div class="value">${d.totals.consultations}</div></div><div class="metric"><span>Consultations / patient</span><div class="value">${(d.totals.consultations/Math.max(1,d.totals.patients)).toLocaleString('fr-FR',{maximumFractionDigits:1})}</div></div><div class="metric emphasis"><span>Recettes</span><div class="value">${euro(d.totals.receipts_cents)}</div></div></div><div class="home-grid"><section class="card card-pad"><h2>Consultations par mois</h2><div style="margin-top:20px">${chart(d.monthly,'count',n=>n)}</div></section><section class="card card-pad"><h2>Moyens de paiement</h2>${d.methods.length?d.methods.map(r=>`<div class="list-row" style="padding-left:0;padding-right:0"><span class="grow">${esc(r.method)}</span><b>${euro(r.cents)}</b></div>`).join(''):'<p class="muted" style="margin-top:20px">Aucun règlement enregistré.</p>'}</section><section class="card card-pad"><h2>Recettes par mois</h2><div style="margin-top:20px">${chart(d.payments,'cents',euro)}</div></section></div>`);}

function modal(title,body,foot=''){const dialog=$('#modal');dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button type="button" class="close-btn" data-action="close-modal" aria-label="Fermer">×</button></div><div class="modal-body">${body}<div class="error-box" id="modal-error" role="alert" hidden></div></div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!dialog.open)dialog.showModal();}
function closeModal(){ $('#modal').close();invoiceEdit=null; }
function formValues(id){return Object.fromEntries(new FormData($(id)));}
function patientForm(edit=false){const p=edit?state.patient:{};modal(edit?'Informations du patient':'Nouveau patient',`<form id="patient-form"><div class="fields">${input('Nom *','last_name',p.last_name,'text','required autocomplete="family-name"')}${input('Prénom *','first_name',p.first_name,'text','required autocomplete="given-name"')}${input('Date de naissance','birth_date',p.birth_date,'date')}<label class="field">Civilité<select name="gender"><option value="">Non renseignée</option>${[['F','Mme'],['M','M.'],['X','Autre / indéterminée']].map(([v,l])=>`<option value="${v}" ${p.gender===v?'selected':''}>${l}</option>`).join('')}</select></label>${input('Téléphone','phone',p.phone,'tel')}${input('Email','email',p.email,'email')}<div class="full">${input('Adresse postale','address',p.address)}</div>${input('Code postal','postal',p.postal)}${input('Ville','city',p.city)}${input('Profession / scolarité','occupation',p.occupation)}${input('Activités','activities',p.activities)}</div></form>`,btn('Annuler','close-modal')+btn(edit?'Enregistrer':'Créer le dossier','save-patient',`data-edit="${edit?'yes':'no'}"`,'primary'));}
async function refreshPatient(){if(state.patient){const co=state.consult?.id;state.patient=await api('/patients/'+state.patient.id);state.consult=state.patient.consultations.find(c=>c.id===co)||state.patient.consultations[0]||null;renderPatient();}}
async function createConsult(){await flush();const p=state.patient;modal('Nouvelle consultation',`<form id="consult-form"><div class="fields">${input('Date de la séance','date',today(),'date','required')}<label class="field">Formulaire<select name="template_id">${state.settings.templates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label></div></form><p class="copy-note">Les notes et antécédents du patient seront disponibles dans cette séance.</p>`,btn('Annuler','close-modal')+btn('Ouvrir la consultation','create-consult','','primary'));}
function antecedentForm(){modal('Ajouter un antécédent',`<form id="antecedent-form"><div class="fields"><label class="field">Catégorie<select name="category">${['Médical','Traumatique','Chirurgical','Familial','Psychologique','Autre'].map(c=>`<option>${c}</option>`).join('')}</select></label>${input('Antécédent *','label','','text','required')}${input('Date ou repère temporel','since','','text','placeholder="Ex. 2022, il y a 3 ans, en cours…"')}<label class="check"><input type="checkbox" name="important">Important</label><div class="full">${area('Détails','detail')}</div></div></form>`,btn('Annuler','close-modal')+btn('Ajouter au dossier','save-antecedent','','primary'));}

async function invoiceById(id){const rows=await api('/invoices');const inv=rows.find(i=>i.id===id);if(!inv)throw new Error('Facture introuvable.');return inv;}
function invoiceEditor(inv){invoiceEdit=structuredClone(inv);renderInvoiceEditor();}
function renderInvoiceEditor(){const inv=invoiceEdit;modal('Préparer la facture',`<form id="invoice-form"><div class="row spread"><span class="badge warm">Brouillon · numéro attribué à l’émission</span><span class="muted small">${day(inv.date)}</span></div><h3 style="margin:24px 0 14px">Destinataire de la facture</h3><div class="fields">${input('Nom *','last_name',inv.recipient.last_name,'text','required')}${input('Prénom','first_name',inv.recipient.first_name)}${input('Email du destinataire','email',inv.recipient.email,'email')}<label class="field">Civilité<select name="gender">${[['','Non renseignée'],['F','Mme'],['M','M.'],['X','Autre']].map(([v,l])=>`<option value="${v}" ${inv.recipient.gender===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="full">${input('Adresse','address',inv.recipient.address)}</div>${input('Code postal','postal',inv.recipient.postal)}${input('Ville','city',inv.recipient.city)}</div><div class="copy-note">Le patient consulté reste lié à la séance, même si la facture porte un autre nom.</div><div class="invoice-lines" id="invoice-lines">${inv.lines.map((l,i)=>`<div class="invoice-line" data-line="${i}">${input('Prestation','line-label-'+i,l.label)}${input('Qté','line-qty-'+i,l.quantity,'number','min="1" step="1"')}${input('Prix TTC (€)','line-price-'+i,(l.unit_cents/100).toFixed(2),'number','min="0" step="0.01"')}${btn('×','remove-line',`data-index="${i}" aria-label="Retirer la ligne ${i+1}"`,'quiet tiny')}</div>`).join('')}</div>${btn('+ Ajouter une ligne','add-line','','quiet tiny')}<div class="invoice-total" id="invoice-total">${euro(inv.total_cents)}</div>${area('Commentaire sur la facture','comment',inv.comment)}</form>`,btn('Supprimer le brouillon','delete-draft','','danger')+btn('Conserver le brouillon','save-draft')+btn('Règlement et émission '+icon('arrow'),'issue-preview','','primary'));}
function collectInvoice(){const f=formValues('#invoice-form');const inv=invoiceEdit;const lines=$$('[data-line]',$('#invoice-form')).map(r=>{const i=r.dataset.line;return {label:f['line-label-'+i],quantity:Number(f['line-qty-'+i]),unit_cents:Math.round(Number(f['line-price-'+i])*100)};});return {recipient:{...inv.recipient,...Object.fromEntries(['last_name','first_name','email','gender','address','postal','city'].map(k=>[k,f[k]]))},lines,comment:f.comment,date:inv.date};}
async function saveInvoice(){if(!$('#invoice-form').reportValidity())return null;const body=collectInvoice();invoiceEdit=await api('/invoices/'+invoiceEdit.id,body);return invoiceEdit;}
function issuePreview(inv){invoiceEdit=inv;modal('Règlement & émission',`<div class="details-list"><div><span class="eyebrow">Destinataire</span><h2 style="margin-top:8px">${name(inv.recipient)}</h2><p class="muted small">${esc(inv.recipient.address)}<br>${esc(inv.recipient.postal+' '+inv.recipient.city)}</p></div><div><span class="eyebrow">Total à encaisser</span><h1 style="margin-top:8px">${euro(inv.total_cents)}</h1></div></div><h3 style="margin:24px 0 12px">Paiement reçu</h3><div class="choice-grid">${['Chèque','Espèces','CB'].map(m=>`<label><input type="radio" name="payment-method" value="${m}">${m}</label>`).join('')}</div><label class="check small muted" style="margin-top:14px"><input type="radio" name="payment-method" value="En attente">Le règlement est encore en attente</label><div class="inline-note">L’émission attribue le numéro définitif. Vous pourrez ensuite télécharger le PDF, l’imprimer ou préparer l’email.</div>`,btn('Revoir le brouillon','back-invoice')+btn('Émettre la facture','issue-invoice','','primary'));}
function invoiceView(inv){if(inv.legacy){mclInvoiceView(inv);return;}invoiceEdit=inv;const replacement=inv.related_id?'<p class="copy-note">Ce document est lié à une correction. Les documents précédents restent dans l’historique.</p>':'';modal(esc((inv.kind==='credit'?'Avoir ':'Facture ')+(inv.number||'Brouillon')),`<div class="row spread">${statusBadge(inv)}<span class="muted small">${day(inv.date)}</span></div><div class="details-list" style="margin-top:22px"><div><div class="eyebrow">Destinataire</div><h2 style="margin-top:7px">${name(inv.recipient)}</h2><p class="muted small">${esc(inv.recipient.address)}<br>${esc(inv.recipient.postal+' '+inv.recipient.city)}</p></div><div><div class="eyebrow">Document</div><div class="invoice-total" style="text-align:left;margin:6px 0">${euro(inv.total_cents)}</div>${inv.kind==='invoice'&&inv.status==='issued'?`<div class="small muted">Réglé : ${euro(inv.paid_cents)}</div>`:''}</div></div><div class="table-wrap"><table><tbody>${inv.lines.map(l=>`<tr><td>${esc(l.label)}</td><td>${l.quantity}</td><td class="numeric">${euro(l.unit_cents*l.quantity*(inv.kind==='credit'?-1:1))}</td></tr>`).join('')}</tbody></table></div>${replacement}${inv.comment?`<p style="margin-top:16px">${esc(inv.comment)}</p>`:''}<div class="row" style="margin-top:24px"><a class="btn primary" href="/api/invoices/${inv.id}/pdf" download>${icon('download')}Télécharger le PDF</a><a class="btn" href="/api/invoices/${inv.id}/pdf?inline=1" target="_blank" rel="noopener">PDF / imprimer</a>${inv.kind==='invoice'&&inv.status==='issued'?`<a class="btn" href="/api/invoices/${inv.id}/email" download>${icon('mail')}Préparer l’email</a>`:''}</div>${inv.kind==='invoice'&&inv.status==='issued'?'<p class="copy-note">L’email est préparé en fichier .eml avec le PDF joint. Ouvrez-le dans une messagerie compatible pour l’envoyer. Aucun email n’est envoyé automatiquement.</p>':''}`,btn('Fermer','close-modal')+btn('Historique','audit-invoice',`data-id="${inv.id}"`)+(inv.status==='draft'?btn('Supprimer le brouillon','delete-draft','','danger')+btn('Modifier le brouillon','back-invoice','','primary'):'')+(inv.kind==='invoice'&&inv.status==='issued'?btn('Corriger la facture','correct-invoice','','')+(inv.paid_cents<inv.total_cents?btn('Enregistrer le règlement','pay-invoice','','primary'):''):''));}
function correctionForm(inv){invoiceEdit=inv;modal('Corriger la facture',`<div class="row spread"><span class="badge subtle">${esc(inv.number)}</span><strong>${euro(inv.total_cents)}</strong></div><p class="muted small" style="margin:14px 0 20px">Seul le champ choisi est corrigé. La prestation, le montant et les autres informations sont conservés.</p><form id="correction-form"><div class="fields"><label class="field">Que faut-il corriger ?<select name="field" id="correction-field">${[['last_name','Nom de famille'],['first_name','Prénom'],['address','Adresse postale'],['postal','Code postal'],['city','Ville'],['gender','Genre / civilité']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><div id="correction-value">${input('Nouvelle valeur','value',inv.recipient.last_name)}</div><div class="full">${input('Motif de la correction','reason','Correction des coordonnées')}</div></div></form><div class="inline-note">Un avoir et une facture corrigée seront créés et liés à l’original. Le règlement enregistré sera rattaché une seule fois au document corrigé. Aucun remboursement ni nouvel encaissement n’est déclenché.</div>`,btn('Annuler','view-current-invoice')+btn('Créer les documents corrigés','confirm-correction','','primary'));}

function migrationSummary(){
  const m=state.settings.migration;if(!m||m.state==='none')return '<p class="copy-note">Aucun import MonCabinetLibéral effectué dans ce cabinet.</p>';
  const s=m.summary;
  return `<div class="inline-note" style="margin-top:12px"><strong>Reprise MonCabinetLibéral</strong><p class="small">${s.active_patients} patients actifs · ${s.archived_patients} fiches archivées · ${s.consultations} consultations · ${s.antecedents} antécédents.</p><p class="copy-note">${s.unlinked_consultations} consultations sans rattachement restent à examiner. Les fichiers sources, factures, règlements et rendez-vous sont conservés localement. Les pièces jointes ne figurent pas dans cet export.</p></div>`;
}

function renderSettings(){const s=settingsEdit||state.settings,p=s.practice,b=s.billing;shell(`<div class="page-head"><div><div class="eyebrow">À votre image</div><h1 style="margin-top:8px">Les paramètres du cabinet</h1><p>Coordonnées, formulaires et numérotation de vos documents.</p></div>${btn(icon('check')+'Enregistrer les paramètres','save-settings','','primary')}</div><div class="settings-grid"><div class="stack"><section class="card card-pad settings-section"><h2>Identité professionnelle</h2><form id="practice-form"><div class="fields">${input('Nom affiché sur les documents *','name',p.name)}${input('Email professionnel','email',p.email,'email')}<div class="full">${input('Adresse *','address',p.address)}</div>${input('Code postal *','postal',p.postal)}${input('Ville *','city',p.city)}${input('SIRET *','siret',p.siret)}${input('RPPS *','rpps',p.rpps)}${input('Téléphone','phone',p.phone)}${input('Mention de TVA / exonération','tax_note',p.tax_note)}<div class="full">${area('Pied de page des factures','footer',p.footer)}</div></div></form></section><section class="card card-pad settings-section"><div class="row spread"><h2>Formulaires de consultation</h2>${btn('+ Formulaire','new-template','','tiny')}</div><p class="muted small" style="margin:12px 0">Motif, anamnèse et notes partagées restent disponibles. Les nouveaux champs s’appliquent aux prochaines consultations.</p><div id="templates-list">${s.templates.map(t=>`<div style="padding:15px 0;border-bottom:1px solid var(--line)"><div class="row spread"><strong>${esc(t.name)}</strong>${btn('+ Champ','new-field',`data-id="${t.id}"`,'tiny')}</div>${t.fields.map((f,i)=>`<div class="template-field"><span class="grow small">${esc(f.label)}</span><span class="small muted">${f.kind==='textarea'?'Texte long':f.kind==='text'?'Texte':f.kind==='checkbox'?'Case':'Liste'}</span>${!['motif','anamnesis'].includes(f.key)?btn('×','remove-field',`data-id="${t.id}" data-key="${f.key}" aria-label="Retirer le champ ${esc(f.label)}"`,'quiet tiny'):''}</div>`).join('')}</div>`).join('')}</div></section></div><div class="stack"><section class="card card-pad settings-section"><h2>Facturation</h2><form id="billing-form"><div class="fields" style="grid-template-columns:1fr">${input('Prestation habituelle','default_label',b.default_label)}${input('Tarif TTC (€)','default_price',(b.default_cents/100).toFixed(2),'number','min="0" step="0.01"')}${input('Format du numéro','format',b.format)}<p class="small muted">{AA} : année courte · {MM} : mois · {N} : compteur annuel.</p>${input('Nombre minimal de chiffres du compteur','padding',b.padding,'number','min="0" max="8"')}<details><summary class="small" style="cursor:pointer">Numérotation avancée</summary><div style="margin-top:15px">${input('Premier compteur de l’année de démarrage','initial_sequence',b.initial_sequence,'number','min="1"')}</div><p class="copy-note">Ce réglage s’applique avant la première émission de l’année de démarrage. Ensuite, la séquence est calculée à partir des documents existants. Au 1er janvier suivant, elle commence à 1.</p><div class="inline-note">Un changement de numéro conserve l’ancien numéro dans l’historique et vérifie les doublons et l’ordre des dates.</div>${btn('Éditer un numéro de facture','renumber-invoice','','tiny')}<div></div></details></div></form></section><section class="card card-pad"><h2>Données locales</h2>${migrationSummary()}<p class="small muted" style="margin:12px 0;overflow-wrap:anywhere">${esc(state.data_dir)}</p>${btn(icon('lock')+'Sauvegarde chiffrée','backup')}<p class="copy-note">Un fichier chiffré contenant les dossiers, les documents et la comptabilité. La phrase de sauvegarde sera nécessaire pour le relire.</p></section><section class="card card-pad"><h2>Apparence</h2><div style="margin-top:15px"><label class="switch"><input type="checkbox" id="theme-toggle" ${document.body.classList.contains('dark')?'checked':''}>Mode sombre</label></div></section><section class="card card-pad"><h3>Version ${esc(state.version)}</h3><p class="copy-note">Les patients et notes MonCabinetLibéral peuvent être repris. L’historique comptable est consultable avec ses contrôles. L’agenda, la fusion et l’envoi direct d’emails restent à construire.</p></section></div></div>`);}
function captureSettings(){if($('#practice-form'))settingsEdit.practice=formValues('#practice-form');if($('#billing-form')){const b=formValues('#billing-form');settingsEdit.billing={...state.settings.billing,format:b.format,padding:Number(b.padding),initial_sequence:Number(b.initial_sequence),default_label:b.default_label,default_cents:Math.round(Number(b.default_price)*100)};}}
function templateFieldForm(id){captureSettings();modal('Ajouter un champ',`<form id="field-form"><div class="fields">${input('Libellé du champ','label','','text','required')}<label class="field">Type<select name="kind" id="field-kind"><option value="textarea">Texte long</option><option value="text">Texte court</option><option value="checkbox">Case à cocher</option><option value="select">Liste de choix</option></select></label><div class="full">${area('Choix possibles — un par ligne, pour une liste','options')}</div></div></form>`,btn('Annuler','close-modal')+btn('Ajouter au formulaire','save-field',`data-id="${id}"`,'primary'));}

document.addEventListener('submit',e=>e.preventDefault());
$('#modal').addEventListener('cancel',e=>{e.preventDefault();runAction('close-modal',{}).catch(errorBox);});

document.addEventListener('input',e=>{
  const el=e.target;
  if(el.dataset.p&&state.patient){const k=el.dataset.p;state.patient[k]=el.value;dirtyP[k]=el.value;$$(`[data-p="${k}"]`).forEach(other=>{if(other!==el)other.value=el.value;});schedule();}
  if(el.dataset.c&&state.consult){const k=el.dataset.c,v=el.type==='checkbox'?el.checked:el.value;state.consult[k]=v;dirtyC[k]=v;if(k==='billable'){$('#billing-explanation').textContent=v?'Cette séance entre dans le suivi de facturation.':'Consultation conservée sans facturation.';if($('#prepare-invoice'))$('#prepare-invoice').disabled=!v;}schedule();}
  if(el.dataset.custom&&state.consult){state.consult.custom[el.dataset.custom]=el.type==='checkbox'?el.checked:el.value;dirtyC.custom={...state.consult.custom};schedule();}
  if(el.id==='patient-search'){const serial=++searchSerial;api('/patients?q='+encodeURIComponent(el.value)+(includeArchived?'&archived=1':'')).then(rows=>{if(serial!==searchSerial||state.route!=='patients')return;state.patients=rows;$('#patient-results').innerHTML=patientsTable(rows);$('#patient-count').textContent=rows.length>=500?'500 premiers résultats — affinez la recherche':rows.length+' dossiers';}).catch(e=>toast(e.message));}
  if(el.id==='invoice-search'){const q=el.value.toLocaleLowerCase('fr');$('#invoice-results').innerHTML=invoiceTable(state.invoices.filter(i=>(i.number+' '+i.recipient.last_name+' '+i.recipient.first_name).toLocaleLowerCase('fr').includes(q)));}
  if(el.closest('#invoice-lines')){const v=collectInvoice();$('#invoice-total').textContent=euro(v.lines.reduce((s,l)=>s+l.quantity*l.unit_cents,0));}
});
document.addEventListener('change',e=>{
  if(e.target.id==='include-archived'){includeArchived=e.target.checked;navigate('patients').catch(errorBox);}
  if(e.target.id==='theme-toggle'){document.body.classList.toggle('dark',e.target.checked);try{localStorage.setItem('cabinet-theme',e.target.checked?'dark':'light');}catch(_){}}
  if(e.target.id==='correction-field'){const k=e.target.value;$('#correction-value').innerHTML=k==='gender'?`<label class="field">Nouvelle civilité<select name="value">${[['','Non renseignée'],['F','Mme'],['M','M.'],['X','Autre']].map(([v,l])=>`<option value="${v}" ${invoiceEdit.recipient.gender===v?'selected':''}>${l}</option>`).join('')}</select></label>`:input('Nouvelle valeur','value',invoiceEdit.recipient[k]);}
  if(e.target.id==='attachment-input')uploadFile(e.target.files[0]).catch(e=>toast(e.message));
});
async function uploadFile(file){if(!file)return;if(file.size>10*1024*1024)throw new Error('Ce fichier dépasse la limite de 10 Mo.');toast('Ajout du document…');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('/attachments',{patient_id:state.patient.id,name:file.name,content:encoded});await refreshPatient();state.tab='documents';renderPatient();toast('Document conservé dans le dossier local.');}

document.addEventListener('click',async e=>{
  const nav=e.target.closest('[data-nav]'),pat=e.target.closest('[data-patient]'),tab=e.target.closest('[data-tab]'),action=e.target.closest('[data-action]');
  try{
    if(nav){await navigate(nav.dataset.nav);return;}
    if(pat){await openPatient(pat.dataset.patient,pat.dataset.consult);return;}
    if(tab){await flush();state.tab=tab.dataset.tab;renderPatient();return;}
    if(!action||action.disabled)return;
    action.disabled=true;
    await runAction(action.dataset.action,action);
  }catch(error){errorBox(error);}finally{if(action&&action.isConnected)action.disabled=false;}
});

async function runAction(action,el){
  if(action.startsWith('mcl-')){await runMclAction(action,el);return;}
  if(action==='retry-save'){await flush();return;}
  if(action==='close-modal'){if($('#modal[open] #invoice-form')){const inv=await saveInvoice();if(!inv)return;}closeModal();await refreshPatient();return;}
  if(action==='nav-patients'){await navigate('patients');return;}
  if(action==='nav-settings'){await navigate('settings');return;}
  if(action==='new-patient'){await flush();patientForm();return;}
  if(action==='edit-patient'){await flush();patientForm(true);return;}
  if(action==='save-patient'){
    if(!$('#patient-form').reportValidity())return;
    const edit=el.dataset.edit==='yes';const body=formValues('#patient-form');if(edit)body.version=state.patient.version;
    const p=await api('/patients'+(edit?'/'+state.patient.id:''),body);closeModal();await openPatient(p.id);toast(edit?'Informations enregistrées.':'Le dossier patient est créé.');return;
  }
  if(action==='open-patient'){await openPatient(el.dataset.id);return;}
  if(action==='new-consult'){await createConsult();return;}
  if(action==='create-consult'){
    if(!$('#consult-form').reportValidity())return;const c=await api('/consultations',{...formValues('#consult-form'),patient_id:state.patient.id});closeModal();state.patient=await api('/patients/'+state.patient.id);state.consult=state.patient.consultations.find(x=>x.id===c.id);state.tab='consultation';renderPatient();setTimeout(()=>$('[data-c="motif"]')?.focus(),0);return;
  }
  if(action==='select-consult'){await flush();state.consult=state.patient.consultations.find(c=>c.id===el.dataset.id);state.tab='consultation';renderPatient();return;}
  if(action==='new-antecedent'){await flush();antecedentForm();return;}
  if(action==='save-antecedent'){if(!$('#antecedent-form').reportValidity())return;const b=formValues('#antecedent-form');b.important=b.important==='on';await api('/antecedents',{...b,patient_id:state.patient.id});closeModal();await refreshPatient();return;}
  if(action==='remove-antecedent'){modal('Retirer cet antécédent ?','<p>L’antécédent sera retiré de la liste. Sa trace restera dans l’historique local.</p>',btn('Conserver','close-modal')+btn('Retirer','confirm-remove-antecedent',`data-id="${el.dataset.id}"`,'danger'));return;}
  if(action==='confirm-remove-antecedent'){await api('/antecedents/'+el.dataset.id+'/delete',{});closeModal();await refreshPatient();return;}
  if(action==='upload'){await flush();$('#attachment-input').click();return;}
  if(action==='consult-pdf'){await flush();const a=document.createElement('a');a.href='/api/consultations/'+state.consult.id+'/pdf';a.download='compte-rendu.pdf';a.click();return;}
  if(action==='prepare-invoice'){await flush();const inv=await api('/invoices',{consultation_id:state.consult.id});if(inv.status==='draft')invoiceEditor(inv);else invoiceView(inv);return;}
  if(action==='view-invoice'){await flush();const inv=await invoiceById(el.dataset.id);if(inv.status==='draft')invoiceEditor(inv);else invoiceView(inv);return;}
  if(action==='view-current-invoice'){invoiceView(invoiceEdit);return;}
  if(action==='save-draft'){const inv=await saveInvoice();if(!inv)return;closeModal();await refreshPatient();if(state.route==='accounting'){state.invoices=await api('/invoices');renderAccounting();}toast('Brouillon enregistré.');return;}
  if(action==='add-line'){Object.assign(invoiceEdit,collectInvoice());invoiceEdit.lines.push({label:'',quantity:1,unit_cents:0});renderInvoiceEditor();return;}
  if(action==='remove-line'){Object.assign(invoiceEdit,collectInvoice());if(invoiceEdit.lines.length===1)throw new Error('Conservez au moins une ligne.');invoiceEdit.lines.splice(Number(el.dataset.index),1);invoiceEdit.total_cents=invoiceEdit.lines.reduce((s,l)=>s+l.quantity*l.unit_cents,0);renderInvoiceEditor();return;}
  if(action==='issue-preview'){const inv=await saveInvoice();if(inv)issuePreview(inv);return;}
  if(action==='back-invoice'){invoiceEditor(invoiceEdit);return;}
  if(action==='issue-invoice'){const method=$('input[name="payment-method"]:checked')?.value;if(!method)throw new Error('Choisissez le moyen de paiement ou En attente.');const inv=await api('/invoices/'+invoiceEdit.id+'/issue',{method});await refreshPatient();if(state.route==='accounting'){state.invoices=await api('/invoices');renderAccounting();}invoiceView(inv);toast('Facture émise : '+inv.number);return;}
  if(action==='delete-draft'){const inv=invoiceEdit;modal('Supprimer le brouillon ?','<p>Ce document n’a pas de numéro définitif. La consultation sera de nouveau disponible pour facturation.</p>',btn('Conserver','close-modal')+btn('Supprimer le brouillon','confirm-delete-draft',`data-id="${inv.id}"`,'danger'));return;}
  if(action==='confirm-delete-draft'){await api('/invoices/'+el.dataset.id+'/delete',{});closeModal();await refreshPatient();if(state.route==='accounting'){state.invoices=await api('/invoices');renderAccounting();}return;}
  if(action==='correct-invoice'){correctionForm(invoiceEdit);return;}
  if(action==='confirm-correction'){const result=await api('/invoices/'+invoiceEdit.id+'/correct',formValues('#correction-form'));await refreshPatient();if(state.route==='accounting'){state.invoices=await api('/invoices');renderAccounting();}invoiceView(result.invoice);toast('Correction enregistrée. Le règlement n’a pas été compté deux fois.');return;}
  if(action==='pay-invoice'){modal('Enregistrer le règlement',`<p style="margin-bottom:18px">Solde : <strong>${euro(invoiceEdit.total_cents-invoiceEdit.paid_cents)}</strong></p><div class="choice-grid">${['Chèque','Espèces','CB'].map(m=>`<label><input type="radio" name="payment-method" value="${m}">${m}</label>`).join('')}</div>`,btn('Annuler','view-current-invoice')+btn('Confirmer le règlement','confirm-payment','','primary'));return;}
  if(action==='confirm-payment'){const method=$('input[name="payment-method"]:checked')?.value;if(!method)throw new Error('Choisissez le moyen de paiement.');const inv=await api('/invoices/'+invoiceEdit.id+'/pay',{method});await refreshPatient();if(state.route==='accounting'){state.invoices=await api('/invoices');renderAccounting();}invoiceView(inv);return;}
  if(action==='audit-consult'){
    await flush();const [consult,patient]=await Promise.all([api('/history/'+state.consult.id),api('/history/'+state.patient.id)]);
    const events=[...consult,...patient].sort((a,b)=>b.id-a.id);
    modal('Historique du dossier et de la séance',auditHtml(events),btn('Fermer','close-modal'));return;
  }
  if(action==='audit-invoice'){
    const events=await api('/history/'+el.dataset.id);modal('Historique du document',auditHtml(events),btn('Retour à la facture','view-current-invoice'));return;
  }
  if(action==='save-settings'){if(!$('#practice-form').reportValidity()||!$('#billing-form').reportValidity())return;captureSettings();state.settings=await api('/settings',settingsEdit);settingsEdit=structuredClone(state.settings);renderSettings();toast('Paramètres enregistrés.');return;}
  if(action==='new-template'){captureSettings();modal('Nouveau formulaire',`<form id="template-form">${input('Nom du formulaire','name','','text','required')}</form>`,btn('Annuler','close-modal')+btn('Ajouter','save-template','','primary'));return;}
  if(action==='save-template'){if(!$('#template-form').reportValidity())return;settingsEdit.templates.push({id:'t_'+crypto.randomUUID().replaceAll('-',''),name:formValues('#template-form').name,fields:[{key:'motif',label:'Motif de consultation',kind:'textarea'},{key:'anamnesis',label:'Anamnèse',kind:'textarea'}]});closeModal();renderSettings();toast('Formulaire ajouté. Enregistrez les paramètres pour le conserver.');return;}
  if(action==='new-field'){templateFieldForm(el.dataset.id);return;}
  if(action==='save-field'){if(!$('#field-form').reportValidity())return;const f=formValues('#field-form');settingsEdit.templates.find(t=>t.id===el.dataset.id).fields.push({key:'f_'+crypto.randomUUID().replaceAll('-',''),label:f.label,kind:f.kind,options:f.options.split('\n').map(s=>s.trim()).filter(Boolean)});closeModal();renderSettings();toast('Champ ajouté. Enregistrez les paramètres pour le conserver.');return;}
  if(action==='remove-field'){captureSettings();const t=settingsEdit.templates.find(t=>t.id===el.dataset.id);t.fields=t.fields.filter(f=>f.key!==el.dataset.key);renderSettings();return;}
  if(action==='renumber-invoice'){
    const rows=(await api('/invoices')).filter(i=>!i.legacy&&i.status==='issued'&&i.kind==='invoice');
    if(!rows.length)throw new Error('Aucune facture émise à renuméroter.');
    modal('Édition avancée du numéro',`<form id="renumber-form"><div class="stack"><label class="field">Facture<select name="id">${rows.map(i=>`<option value="${i.id}">${esc(i.number)} · ${name(i.recipient)}</option>`).join('')}</select></label>${input('Nouveau numéro complet','number','','text','required')}${input('Motif du changement','reason','','text','required')}</div></form><p class="copy-note">Le montant, le destinataire et le règlement sont conservés. L’ancien numéro restera dans l’historique et ne pourra pas être réattribué.</p>`,btn('Annuler','close-modal')+btn('Vérifier et enregistrer','confirm-renumber','','primary'));return;
  }
  if(action==='confirm-renumber'){
    if(!$('#renumber-form').reportValidity())return;
    const body=formValues('#renumber-form');const inv=await api('/invoices/'+body.id+'/renumber',body);
    invoiceView(inv);toast('Numéro enregistré : '+inv.number);return;
  }
  if(action==='backup'){modal('Sauvegarde chiffrée',`<form id="backup-form"><div class="stack">${input('Phrase de sauvegarde — au moins 12 caractères','password','','password','minlength="12" required autocomplete="new-password"')}${input('Répéter la phrase','confirm','','password','required autocomplete="new-password"')}</div></form><p class="copy-note">Conservez cette phrase séparément. Elle n’est pas stockée par le logiciel et sera nécessaire pour récupérer les données.</p>`,btn('Annuler','close-modal')+btn('Créer la sauvegarde','create-backup','','primary'));return;}
  if(action==='create-backup'){if(!$('#backup-form').reportValidity())return;const b=formValues('#backup-form');if(b.password!==b.confirm)throw new Error('Les deux phrases ne correspondent pas.');const res=await fetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json','X-Cabinet-Token':$('meta[name="cabinet-token"]').content},body:JSON.stringify({password:b.password})});if(!res.ok)throw new Error((await res.json()).error);const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.download='cabinet-'+today()+'.mco';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);closeModal();toast('Sauvegarde chiffrée préparée.');return;}
}

function auditHtml(events){
  const labels={first_name:'Prénom',last_name:'Nom',birth_date:'Naissance',gender:'Civilité',phone:'Téléphone',email:'Email',address:'Adresse',postal:'Code postal',city:'Ville',occupation:'Profession',activities:'Activités',shared_notes:'Notes / antécédents',important_notes:'Notes importantes',motif:'Motif',anamnesis:'Anamnèse',followup:'Prochain rendez-vous',billable:'Facturer',date:'Date',number:'Numéro',reason:'Motif de correction',method:'Paiement',total_cents:'Montant',cents:'Règlement',field:'Champ corrigé',value:'Nouvelle valeur'};
  const kinds={'patient.created':'Création de la fiche','patient.updated':'Fiche patient','consultation.created':'Ouverture de la séance','consultation.updated':'Consultation','invoice.draft':'Brouillon','invoice.issued':'Émission','invoice.corrected':'Correction','invoice.renumbered':'Changement de numéro','payment.created':'Règlement'};
  return events.map(event=>{
    const after=JSON.parse(event.after_json),before=JSON.parse(event.before_json||'{}');
    const changes=Object.keys(after).filter(k=>labels[k]&&after[k]!==before[k]).map(k=>{
      const format=v=>k.endsWith('cents')?euro(v):k==='billable'?(v?'Oui':'Non'):esc(String(v??''));
      return `<div style="margin-top:12px"><strong>${labels[k]}</strong>${before[k]!==undefined?`<p class="muted small" style="white-space:pre-wrap">Avant : ${format(before[k])||'Vide'}</p>`:''}<p class="small" style="white-space:pre-wrap">${format(after[k])||'Champ vidé'}</p></div>`;
    }).join('');
    return `<details class="history-item"><summary>${esc(new Date(event.at).toLocaleString('fr-FR'))} · ${esc(kinds[event.kind]||'Modification')}</summary>${changes||'<p class="copy-note">Opération conservée dans l’historique.</p>'}</details>`;
  }).join('')||'<p>Aucune modification.</p>';
}

async function init(){try{const boot=await api('/bootstrap');Object.assign(state,boot);const hash=location.hash.slice(1);if(hash.startsWith('patient/')){await openPatient(hash.split('/')[1]);}else{await navigate(['home','patients','accounting','statistics','settings','orphans'].includes(hash)?hash:'home');}}catch(e){$('#app').innerHTML=`<div class="loading"><h2>Le cabinet n’a pas pu s’ouvrir</h2><p style="margin:18px">${esc(e.message)}</p><button class="btn" id="reload">Réessayer</button></div>`;$('#reload').addEventListener('click',()=>location.reload());}}
init();
